// src/frontend/HomeworkPage.tsx
import { useEffect, useState } from "react";

export const route = "/homeworks";

type Row = { id: number; title: string };

export function HomeworkPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/homeworks")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Homework</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

