# src/network/homework_api.py
from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["homework"])


@router.get("/api/homeworks")
async def list_homeworks(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM homework ORDER BY id DESC")


@router.post("/api/homeworks")
async def create_homework(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO homework (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/homeworks/{item_id}")
async def get_homework(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM homework WHERE id = $1", item_id)

