// src/network/homework_client.ts
export type Homework = { id: number; title: string };

type NewHomework = Omit<Homework, "id">;

export async function listHomework(): Promise<Homework[]> {
  const res = await fetch("/api/homeworks");
  return res.json();
}

export async function createHomework(payload: NewHomework): Promise<Homework> {
  const res = await fetch("/api/homeworks", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

