// src/frontend/StylistPage.tsx
import { useEffect, useState } from "react";

export const route = "/stylists";

type Row = { id: number; title: string };

export function StylistPage() {
  const [rows, setRows] = useState<Row[]>([]);

  useEffect(() => {
    fetch("/api/stylists")
      .then((res) => res.json())
      .then(setRows);
  }, []);

  return (
    <section>
      <h1>Stylist</h1>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.title}</li>
        ))}
      </ul>
    </section>
  );
}

