from fastapi import APIRouter, Depends

from src.auth.session import require_session
from src.database.db import db

router = APIRouter(tags=["stylist"])


@router.get("/api/stylists")
async def list_stylists(user: dict = Depends(require_session)):
    return await db.fetch("SELECT * FROM stylist ORDER BY id DESC")


@router.post("/api/stylists")
async def create_stylist(payload: dict, user: dict = Depends(require_session)):
    return await db.fetchrow(
        "INSERT INTO stylist (owner_id, title) VALUES ($1, $2) RETURNING *",
        user["id"], payload.get("title"),
    )


@router.get("/api/stylists/{item_id}")
async def get_stylist(item_id: int, user: dict = Depends(require_session)):
    return await db.fetchrow("SELECT * FROM stylist WHERE id = $1", item_id)

