// src/network/stylist_client.ts
export type Stylist = { id: number; title: string };

type NewStylist = Omit<Stylist, "id">;

export async function listStylist(): Promise<Stylist[]> {
  const res = await fetch("/api/stylists");
  return res.json();
}

export async function createStylist(payload: NewStylist): Promise<Stylist> {
  const res = await fetch("/api/stylists", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

