export type Pupil = { id: number; title: string };

type NewPupil = Omit<Pupil, "id">;

export async function listPupil(): Promise<Pupil[]> {
  const res = await fetch("/api/pupils");
  return res.json();
}

export async function createPupil(payload: NewPupil): Promise<Pupil> {
  const res = await fetch("/api/pupils", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  return res.json();
}

